        for (let i = 0; i < knownParams.gusts.length; i++) {
          const g = knownParams.gusts[i];
          if (tLook >= g.start && tLook < g.start + g.duration) {
            wx += g.x; wz += g.z;
          }
        }
        windAccX = (0.42 * wx) / knownParams.mass + 0.35 * distX;
        windAccZ = (0.42 * wz) / knownParams.mass + 0.35 * distZ;
