          } else {
            target = { x: pad.x, y: 0.04, z: pad.z };
            targetVel = { x: 0, y: p.y > 0.14 ? -0.25 : -0.10, z: 0 };
          }
        }
      }

      const ex = target.x - p.x;
      const ey = target.y - p.y;
      const ez = target.z - p.z;

      // Position error saturation so large errors give smooth max velocity approach
      const posLim = phase === 'cross' ? 0.55 : 0.70;
      const exClamped = clamp(ex, -posLim, posLim);
      const ezClamped = clamp(ez, -posLim, posLim);

      // Tighter Y/Z gains during gate alignment & crossing
      const inGate = obs.gateIndex < 3 && Math.abs(p.x - obs.nextGate.centre.x) < 0.55;
      const kpX = phase === 'cross' ? 4.8 : 4.2;
      const kdX = 3.6;
