      } else {
        intX *= 0.98;
        intZ *= 0.98;
      }

      const dragCompX = (0.42 * v.x) / estMass;
      const dragCompZ = (0.42 * v.z) / estMass;

      const ax = clamp(kpX * exClamped + kdX * (targetVel.x - v.x) + 1.5 * intX - windAccX + dragCompX, -4.2, 4.2);
      const az = clamp(kpZ * ezClamped + kdZ * (targetVel.z - v.z) + 2.2 * intZ - windAccZ + dragCompZ, -4.2, 4.2);

      intY = clamp(intY + ey * dt, -0.8, 1.8);
