        rollCmd *= 0.5;
      }

      thrust = clamp(thrust, 0, 1);
      prevPos = { x: p.x, y: p.y, z: p.z };
      prevVel = { x: v.x, y: v.y, z: v.z, lastThrust: thrust };

      return { thrust, roll: rollCmd, pitch: pitchCmd, yawRate: clamp(-2.5 * att.yaw, -2, 2) };
    },
  };
}

